f='people-list.ts'
s=open(f).read()
old='''              <td data-testid="rollup-knot-top">{{ knotTop() ?? 'n/a' }}</td>
              <td colspan="16"></td>
            </tr>
'''
new=old+'''            <tr>
              <th scope="row" colspan="33">Knot spread</th>
              <td data-testid="rollup-knot-spread">{{ knotSpread() ?? 'n/a' }}</td>
              <td colspan="16"></td>
            </tr>
'''
assert s.count(old)==1
s=s.replace(old,new)
old2='''      .map((p) => p.knot)
      .filter((v): v is number => v !== null);
    return values.length === 0 ? null : Math.max(...values);
  });
'''
new2=old2+'''
  // The highest knot minus the lowest among the people not on hold (n/a knots skipped);
  // null (n/a) when nobody has one.
  protected readonly knotSpread = computed(() => {
    const values = (this.people() ?? [])
      .filter((p) => !p.hold)
      .map((p) => p.knot)
      .filter((v): v is number => v !== null);
    return values.length === 0 ? null : Math.max(...values) - Math.min(...values);
  });
'''
assert s.count(old2)==1
s=s.replace(old2,new2)
open(f,'w').write(s)
